// Usually you need the 'dotenv' package to read from a .env file:
// require('dotenv').config();

// For this example, we will manually inject a variable into the environment:
process.env.API_KEY = "super_secret_123";
process.env.NODE_ENV = "production";

// Using the variables in your code
console.log("Connecting to Stripe with API Key:", process.env.API_KEY);

if (process.env.NODE_ENV === 'production') {
  console.log("Running in PRODUCTION mode. Logging is minimized.");
} else {
  console.log("Running in DEV mode. Verbose logging enabled.");
}

// Fallback pattern (highly recommended)
const port = process.env.PORT || 3000;
console.log(`Server starting on port ${port}...`);
